  'Samenvoegen tot Overig': 'Għaqqad f\'Ieħor',
  'Toon hoeveel items verborgen zijn': 'Uri kemm-il element huwa moħbi',
  'Toon alleen een deel van de bullets, tabel of grafiek. De oorspronkelijke data blijft in het bestand bewaard.':
      'Uri biss parti mill-bullets, mit-tabella jew mill-grafika. Id-data oriġinali tibqa\' maħżuna fil-fajl.',
  'Voor tabellen: kolomindex of naam om op te sorteren. Voor grafieken: naam van de reeks.':
      'Għat-tabelli: l-indiċi jew l-isem tal-kolonna għall-issortjar. Għall-grafiki: l-isem tas-serje.',
  'Online opslag is alleen beschikbaar in de desktopversie.':
      'Il-ħażna online hija disponibbli biss fil-verżjoni desktop.',
  'Online opslag': 'Ħażna online',
  'Presentaties openen uit en opslaan naar WebDAV, S3 en git-repository’s, met versiebeheer en samenwerken via een forge. Een deel van deze paden is tot nu toe vooral tegen testomgevingen beproefd; kies dit bewust. Zonder de module werkt alles lokaal gewoon: mappen, bestanden en pakketten.':
      'Iftaħ preżentazzjonijiet minn u issejvja lejn WebDAV, S3 u repożitorji git, b\'kontroll tal-verżjonijiet u kollaborazzjoni permezz ta\' forge. Parti minn dawn it-toroq s\'issa ġiet ippruvata l-aktar kontra ambjenti tat-test; agħżel dan konxjament. Mingħajr il-modulu kollox lokali jaħdem normali: folders, fajls u pakketti.',
  'Er staan al online verbindingen ingesteld; die blijven werken, net als wachtend werk in de wachtrij. Uit betekent alleen: geen nieuwe online verbindingen toevoegen.':
      'Diġà hemm konnessjonijiet online konfigurati; dawn jibqgħu jaħdmu, bħax-xogħol li qed jistenna fil-kju. Mitfi jfisser biss: ma jiżdiedux konnessjonijiet online ġodda.',
  'De module AI-assistentie staat uit, dus hier gebeurt niets. Zet hem aan bij Uitbreidingen. Wat je hieronder hebt ingesteld blijft staan.':
      'Il-modulu Assistenza AI huwa mitfi, għalhekk hawnhekk ma jiġri xejn. Ixegħlu taħt Estensjonijiet. Dak li ssettjajt hawn taħt jibqa\' kif inhu.',
  'Hulp bij alt-teksten, beschrijvingen en formuleringen. Aanzetten verstuurt nog niets: dat gebeurt pas nadat je zelf een backend hebt gekozen en, bij een clouddienst, uitdrukkelijk hebt bevestigd. Een lokale backend verlaat je computer niet.':
      'Għajnuna b\'testi alternattivi, deskrizzjonijiet u formulazzjonijiet. Meta tixgħlu xorta ma jintbagħat xejn: dan iseħħ biss wara li tagħżel backend int stess u, fil-każ ta\' servizz cloud, tikkonferma espliċitament. B\'backend lokali xejn ma joħroġ mill-kompjuter tiegħek.',
  'Kies de backend op het tabblad AI-assistentie. Zolang daar niets staat, gebeurt er niets.':
      'Agħżel il-backend fit-tab Assistenza AI. Sakemm m\'hemm xejn hemmhekk, ma jiġri xejn.',
  'De voorbeelddia\'s van een sjabloon staan in het Engels. Naam en omschrijving volgen je eigen taal; de inhoud pas je na het aanmaken aan.':
      'Is-slides ta\' eżempju ta\' mudell huma bl-Ingliż. L-isem u d-deskrizzjoni jsegwu l-lingwa tiegħek; il-kontenut taddattah wara l-ħolqien.',
  'Meer': 'Aktar',
  'Leesbaarheid van dit profiel': 'Il-leġibbiltà ta\' dan il-profil',
  'Alle onderdelen halen de norm.':
      'Il-partijiet kollha jissodisfaw l-istandard.',
  'Deze verhoudingen gaan over de app zelf, niet over je dia\'s.':
      'Dawn il-proporzjonijiet jirrigwardaw l-app innifisha, mhux is-slajds tiegħek.',
  'Tekst op kaarten en dialogen': 'Test fuq karti u djalogi',
  'Tekst op de schermachtergrond': 'Test fuq l-isfond tal-iskrin',
  'Tekst en pictogrammen in de zijbalk': 'Test u ikoni fil-barra tal-ġenb',
  'Titel in de bovenbalk': 'Titlu fil-barra ta\' fuq',
  'Tekstknoppen en links': 'Buttuni ta\' test u links',
  'Selectievakjes, schakelaars en de tekstcursor':
      'Kaxxi ta\' għażla, swiċċijiet u l-kursur tat-test',
  'Het vinkje in een aangevinkt vakje': 'It-tikka f\'kaxxa mmarkata',
  'Label op de primaire knop': 'It-tikketta fuq il-buttuna primarja',
  'Bevindingen die je hebt beoordeeld en hebt laten staan. Ze worden niet meer gemeld, maar de scan blijft ze vinden en ze tellen niet als opgelost. Tik om er een terug te zetten.':
      'Sejbiet li rrevedejt u ħallejt kif inhuma. Dawn ma jiġux irrapportati aktar, iżda l-iskennjar xorta jsibhom u ma jgħoddux bħala solvuti. Mess biex terġa\' ddaħħal waħda.',
  'Deze is beoordeeld en mag blijven': 'Rivedut, dan jista\' jibqa\'',
  'Mogelijk gemaakt door': 'Sar possibbli minn',
  'De export is gestopt tijdens het voorbereiden.':
      'L-esportazzjoni waqfet waqt it-tħejjija.',
  'Het bestand kon niet worden opgebouwd of weggeschreven. Controleer of er schijfruimte is en of de exportmap beschrijfbaar is.':
      'Il-fajl ma setax jinbena jew jinkiteb. Iċċekkja li hemm spazju fuq id-diska u li l-folder tal-esportazzjoni jista\' jinkiteb.',
  'Het renderen van de dia\'s naar beeld is mislukt. Dit ligt aan een dia, niet aan het bestandsformaat: de HTML-export komt hier niet langs en werkt in dit geval meestal wel.':
      'Ir-rendering tal-islajds f\'immaġni falla. Dan ġej minn slajd, mhux mill-format tal-fajl: l-esportazzjoni HTML ma tgħaddix minn hawn u f\'dan il-każ ġeneralment taħdem.',
