  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'jelenka x\'tħalla barra, mingħajr il-valuri nfushom. Dan il-fajl jista\' jintbagħat mar-rapport.',
