  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Dawn is-slides ma jitteħdux waqt il-preżentazzjoni, l-esportazzjoni jew fil-pakkett. Għolli l-livell TLP tal-preżentazzjoni f\'Informazzjoni tal-preżentazzjoni biex tinkludihom.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Is-slides kollha huma miżmuma minħabba l-klassifikazzjoni TLP tagħhom — m\'hemm xejn x\'juri.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Is-slides kollha huma miżmuma minħabba l-klassifikazzjoni TLP tagħhom — m\'hemm xejn x\'jiġi esportat.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Is-slides kollha nqabżu jew huma miżmuma minħabba l-klassifikazzjoni TLP tagħhom — m\'hemm xejn x\'juri.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Is-slides kollha nqabżu jew huma miżmuma minħabba l-klassifikazzjoni TLP tagħhom — m\'hemm xejn x\'jiġi esportat.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Iċ-ċifri tal-graffs ma ġewx issalvati — jinsabu biss f\'din it-tieqa:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Fil-browser m\'hemmx irkupru wara ħabta: jekk tagħlaq din it-tab, ix-xogħol mhux issalvat jintilef. Issalva l-preżentazzjoni tiegħek int stess.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Id-database CVE lokali (id-download tibdieh int stess): OciDeck iġib id-data bl-ingrossa permezz ta\' api.github.com u l-fajl tal-ħruġ li dak l-indirizz jipponta lejh.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Tfittxija CVE (mitfija awtomatikament): meta tkun mixgħula, il-kelma li tfittex tmur lejn il-mera CVE issettjata u, jekk dik ma ssib xejn, lejn id-database Ewropea tal-ENISA u lejn MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Vidjow inkorporat minn YouTube jew Vimeo jgħabbi l-plejer minn dak is-servizz.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Fil-brawżer: jekk il-brawżer jirrifjuta li jġib indirizz direttament, OciDeck jerġa\' jipprova permezz tas-server li minnu ġiet l-app; dak l-indirizz imbagħad jasal għand dak is-server.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'L-irtirar ma ġiex issejvjat. Fil-bidu li jmiss il-kunsens tiegħek ikun validu mill-ġdid.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Intestatura ta\' taqsima li tħabbar parti ġdida tal-preżentazzjoni. Żommha qasira. Żid immaġni ta\' sfond mil-librerija tal-immaġini.',
  'Bronnen doorzoeken…': 'Tfittex fis-sorsi…',
  'Niet doorzocht': 'Mhux imfittex',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Din il-verifika ma taħdimx fil-verżjoni tal-web: is-sejbien tal-uċuħ jeħtieġ librerija tas-sistema li l-browser m\'għandux. Uża l-verżjoni tad-desktop biex tiċċekkja l-uċuħ fl-istampi.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'It-token jeħtieġ aċċess ta\' qari u kitba għar-repożitorju. Gitea u Forgejo m\'għandhomx tfittxija fis-server; OciDeck ifittex lokalment.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'It-token jeħtieġ l-ambitu repo (jew fin: Contents qari u kitba).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'It-token jeħtieġ read_repository, write_repository u read_api. It-tfittxija fis-server teħtieġ Advanced jew Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Tfittxija mgħaġġla fis-server — minħabba dewmien fl-indiċjar, deck li għadu kif inbidel jista\' jonqos.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Il-media ma tinżammx f\'fajl .md sempliċi',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'L-istampi, il-vidjo u l-awdjo li għażilt f\'din it-tab jeżistu biss fil-memorja. Fajl .md sempliċi ma jżommhomx — jintilfu meta terġa\' tiftħu. Esporta bħala pakkett .ocideck biex tieħu l-media miegħek.',
  'Media verwijderd om privacyredenen':
      'Il-media tneħħiet għal raġunijiet ta\' privatezza',
