      'Iwissi biss riżultat ċert; probabbli u possibbli jibqgħu informattivi. Regola mitfija ma tiskatta mkien.',
  'Niet gecontroleerd: persoonsgegevens, bijzondere gegevens en geheimen. De privacycontrole staat uit bij Beveiliging.':
      'Mhux iċċekkjat: data personali, data speċjali u sigrieti. Il-kontroll tal-privatezza huwa mitfi taħt Sigurtà.',
  'Op deze slide': 'F\'din is-slide',
  'Tijdens presenteren': 'Waqt il-preżentazzjoni',
  'Classificatie en privacy': 'Klassifikazzjoni u privatezza',
  'Logo tonen': 'Uri l-logo',
  'Footer tonen': 'Uri l-footer',
  'Tabel bewerkbaar': 'Tabella editabbli',
  'Laat je de tabel tijdens het presenteren voor de zaal aanpassen. Staat standaard uit.':
      'Iħallik tbiddel it-tabella quddiem l-udjenza waqt il-preżentazzjoni. Mitfi awtomatikament.',
  'Automatisch doorgaan': 'Kompli awtomatikament',
  'Persoonsgegevens': 'Data personali',
  'Wijzigen': 'Ibdel',
  'Automatisch afspelen': 'Daqq awtomatikament',
  'Melden': 'Irrapporta',
  'Geaccepteerd': 'Aċċettat',
  'Gewaarschuwd': 'Imwissi',
  'Weggelaten': 'Imħolli barra',
  'Bewerkbaar': 'Editabbli',
  'De privacycontrole': 'Il-kontroll tal-privatezza',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck jaqra s-slides tiegħek għal data li tista\' tkun sensittiva għall-privatezza: numri ta\' identifikazzjoni, dettalji ta\' kuntatt, numri tat-telefon, kontijiet bankarji, ċwievet u passwords, u kategoriji speċjali ta\' data personali. Dan kollu jseħħ fuq dan l-apparat: xejn ma jintbagħat, u l-valur misjub ma jidher f\'ebda avviż.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Il-kontroll ma jiggarantixxix li kollox jinstab; inaqqas iċ-ċans li data personali tinxtered mingħajr ma trid.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'It-test fl-istampi jibqa\' barra mill-vista, il-fajls marbuta ma jinfetħux, u l-ebda skener ma jagħraf data mingħajr mudell rikonoxxibbli. Slide mingħajr sejbiet hija slide li fiha *aħna* ma sibna xejn — mhux slide li ġie ppruvat li ma fiha xejn. Dak li taqsam jibqa\' d-deċiżjoni tiegħek u r-responsabbiltà tiegħek.',
  'telefoonnummer': 'numru tat-telefon',
  'Voor wie is deze export?': 'Għal min hi din l-esportazzjoni?',
  'Volledig': 'Sħiħ',
  'Geredigeerd': 'Irrediġut',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Għall-klijent jew l-awditur: jitneħħa biss dak li ssettjajt bħala "ħalli barra". Il-bqija jibqa\' jinqara, biex parti terza tkun tista\' tivverifika s-sejbiet.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Għal ċirku usa\': jitneħħa kollox li ssib il-kontroll, anke fuq slides li aċċettajt. Il-fajl jieħu "-geredigeerd" f\'ismu.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'tabella ta\' data personali (ringieli×kolonni)',
  'massa-persoonsgegevens op één slide':
      'data personali bl-ingrossa fuq slide waħda',
  'gebruikerspad met een naam erin': 'path tal-utent b\'isem fih',
  'toegangstoken in een link': 'token ta\' aċċess f\'link',
  'persoonsgegeven in een link': 'data personali f\'link',
  'deellink met ingebakken toegang': 'link ta\' qsim b\'aċċess inkorporat',
  'e-mailadres in een link': 'indirizz tal-email f\'link',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'immaġni inkorporata — ma nistgħux inħarsu ġewwa',
  'Je eigen gegevens': 'Id-dettalji tiegħek stess',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Wieħed f\'kull linja: ismek, l-indirizz email, in-numru tat-telefon jew id-dominju tal-organizzazzjoni tiegħek. Dak li hemm hawn ma jiġix irrapportat u lanqas irrediġut — huwa min jibgħat, mhux sejba. Dominju (example.org) ikopri kull indirizz taħtu.',
  'Bij onafgehandelde persoonsgegevens': 'B\'data personali mhux solvuta',
  'Export afgebroken vanwege privacybevindingen.':
      'L-esportazzjoni ġiet ikkanċellata minħabba sejbiet ta\' privatezza.',
  'Export blokkeren': 'Imblokka l-esportazzjoni',
  'Export geblokkeerd': 'L-esportazzjoni mblukkata',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'L-esportazzjoni mblukkata: din il-preżentazzjoni fiha data personali li għadek ma ddeċidejtx dwarha.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
      'Agħżel għal kull slide x\'għandu jsir, jew esporta b\'mod konxju kif inhu.',
  'Maak per slide een keuze (accepteren, waarschuwen of weglaten) voordat je exporteert. Dit is zo ingesteld bij Beveiliging.':
      'Agħmel għażla għal kull slide (aċċetta, wissi jew ħalli barra) qabel tesporta. Dan huwa ssettjat taħt Sigurtà.',
  'Niets doen': 'Tagħmel xejn',
  'Persoonsgegevens in dit deck': 'Data personali f\'din il-preżentazzjoni',
  'Verder in dit deck:': 'Band\'oħra f\'din il-preżentazzjoni:',
  'Waarschuwen vóór export': 'Wissi qabel l-esportazzjoni',
  'bevinding(en) zonder keuze.': 'sejba/sejbiet mingħajr għażla.',
  'geaccepteerd': 'aċċettati',
  'geredigeerd': 'irrediġuti',
  'met waarschuwing': 'b\'twissija',
  'Deze regel nooit meer melden': 'Qatt aktar tirrapporta din ir-regola',
  'politieke opvatting': 'opinjoni politika',
  'etnische afkomst': 'oriġini etnika',
  'seksuele geaardheid': 'orjentazzjoni sesswali',
  ' Op deze slide staat ook een identificerend gegeven, dus dit is herleidbaar tot een persoon.':
      ' F\'din is-slide hemm ukoll dettall li jidentifika, allura dan jista\' jintrabat ma\' persuna.',
  'Bijzonder persoonsgegeven (AVG art. 9/10)':
      'Kategorija speċjali ta\' data personali (GDPR art. 9/10)',
