  'strafrechtelijk gegeven': 'data kriminali',
  'religie of levensovertuiging': 'reliġjon jew twemmin',
  'vakbondslidmaatschap': 'sħubija f\'unjin',
  'biometrisch gegeven': 'data bijometrika',
  'genetisch gegeven': 'data ġenetika',
  'parketnummer': 'numru tal-kawża tal-prosekuzzjoni',
  'nationaal identificatienummer': 'numru ta\' identifikazzjoni nazzjonali',
  'Mogelijk geheim': 'Sigriet possibbli',
  'sleutel of token': 'ċavetta jew token',
  'private sleutel': 'ċavetta privata',
  'toegangstoken (JWT)': 'token ta\' aċċess (JWT)',
  'databaseverbinding met wachtwoord': 'konnessjoni tad-database bil-password',
  'wachtwoord in klare tekst': 'password f\'test ċar',
  'Afbreken': 'Ikkanċella',
  'Afgebroken. Er is niets half achtergebleven.':
      'Ikkanċellat. Ma baqa\' xejn nofsu lest.',
  'Bijwerken': 'Aġġorna',
  'Binnenhalen…': 'Qed jitniżżel…',
  'CVE\'s': 'CVE',
  'Database ophalen': 'Niżżel id-database',
  'De CVE-lijst kon niet worden opgehaald. Controleer je verbinding en probeer het opnieuw; een half binnengehaalde lijst is weggegooid.':
      'Il-lista tas-CVE ma setgħetx tinġieb. Iċċekkja l-konnessjoni tiegħek u erġa\' pprova; lista mniżżla nofsha ntremiet.',
  'De nieuwste uitgave opzoeken…': 'Qed tinstab l-aħħar verżjoni…',
  'Dit is een grote download: ruim 500 MB binnenhalen, tijdelijk zo\'n 1,5 GB schijfruimte, en afhankelijk van je verbinding en apparaat al gauw tien tot dertig minuten werk. Daarna blijft er een index van enkele honderden megabytes staan. Op een verbinding die per megabyte betaalt, doe je dit liever niet.':
      'Dan huwa download kbir: aktar minn 500 MB x\'tniżżel, temporanjament madwar 1,5 GB spazju fuq id-diska, u skont il-konnessjoni u l-apparat tiegħek faċilment għaxar sa tletin minuta xogħol. Wara jibqa\' indiċi ta\' xi mitt megabajt jew tnejn. Fuq konnessjoni li titħallas bil-megabajt, aħjar ma tagħmilx dan.',
  'Er was te weinig schijfruimte. De opbouw vraagt tijdelijk ruim 1,5 GB.':
      'Ma kienx hemm biżżejjed spazju fuq id-diska. Il-bini jitlob temporanjament aktar minn 1,5 GB.',
  'Het opgehaalde archief was niet wat we verwachtten en is geweigerd. Er is niets geïnstalleerd.':
      'L-arkivju mniżżel ma kienx dak li stennejna u ġie miċħud. Ma ġie installat xejn.',
  'Indexeren…': 'Qed jiġi indiċjat…',
  'Lokaal beschikbaar — opzoeken gebeurt offline, er gaat geen zoekterm naar buiten.':
      'Disponibbli lokalment — it-tfittxija ssir offline, l-ebda terminu ta\' tfittxija ma joħroġ barra.',
  'Lokale CVE-database': 'Database CVE lokali',
  'Met de CVE-lijst op je eigen apparaat blijft het opzoeken hier: er gaat geen zoekterm meer naar een server, en niemand kan zien welk lek je onderzoekt.':
      'Bil-lista tas-CVE fuq l-apparat tiegħek stess, it-tfittxija tibqa\' hawn: l-ebda terminu ta\' tfittxija ma jmur aktar għand server, u ħadd ma jista\' jara liema vulnerabbiltà qed tinvestiga.',
  'Uitpakken…': 'Qed jinħareġ…',
  'Zet de volledige CVE-lijst op dit apparaat, zodat opzoeken offline gebeurt en je zoekterm nergens heen gaat. De database komt van CVE List V5 (het officiële CVE-programma, via GitHub).':
      'Poġġi l-lista sħiħa tas-CVE fuq dan l-apparat, biex it-tfittxija ssir offline u t-terminu ta\' tfittxija tiegħek ma jmur imkien. Id-database tiġi minn CVE List V5 (il-programm uffiċjali tas-CVE, permezz ta\' GitHub).',
  'Wat er lokaal beschikbaar is': 'X\'inhu disponibbli lokalment',
  'Nu bijwerken': 'Aġġorna issa',
  'Gegevens lokaal beschikbaar — het opzoeken gebeurt op dit apparaat, er gaat niets naar buiten.':
      'Data disponibbli lokalment — it-tfittxija ssir fuq dan l-apparat; xejn ma joħroġ.',
  'Zwakheden (CWE)': 'Dgħufijiet (CWE)',
  'Testgevallen (WSTG)': 'Każijiet ta\' test (WSTG)',
  'MIAUW-eisen': 'Rekwiżiti MIAUW',
  'CVSS-scoretabel': 'Tabella tal-punteġġ CVSS',
  'Bevindingsjablonen': 'Mudelli tas-sejbiet',
  'Zoek een instelling': 'Fittex issettjar',
  'Geen instelling gevonden': 'Ma nstab l-ebda issettjar',
  'Je zoekterm gaat naar de ingestelde CVE-mirror, en als die niets vindt ook naar ENISA en MITRE. Wie die servers beheert, kan daaruit afleiden naar welk specifiek lek je zoekt — en dus welk lek je onderzoekt.':
      'It-terminu tat-tfittxija tiegħek jintbagħat lill-mirror CVE konfigurat, u jekk dak ma jsib xejn, anke lil ENISA u MITRE. Min imexxi dawk is-servers jista\' jiddeduċi liema vulnerabbiltà speċifika qed tfittex — u għalhekk liema vulnerabbiltà qed tinvestiga.',
  'Accepteren': 'Aċċetta',
  'Accepteren + waarschuwen': 'Aċċetta + wissi',
  'Accepteren: de gegevens horen hier en de melding verdwijnt. Accepteren + waarschuwen: de ontvanger ziet een badge dat er persoonsgegevens op de slide staan. Weglaten: de gevonden gegevens worden onleesbaar gemaakt op het scherm en in de export — je markdown-bestand houdt de oorspronkelijke tekst.':
      'Aċċetta: id-data tappartjeni hawn u l-avviż jisparixxi. Aċċetta + wissi: min jirċievi jara badge li s-slide fiha data personali. Ħalli barra: id-data misjuba ssir illeġġibbli fuq l-iskrin u fl-esportazzjoni — il-fajl Markdown tiegħek iżomm it-test oriġinali.',
  'Alleen melden': 'Irrapporta biss',
  'PERSOONSGEGEVENS': 'DATA PERSONALI',
  'Volg de presentatie': 'Segwi l-preżentazzjoni',
  'Weglaten uit tonen en exporteren': 'Ħalli barra mill-wiri u l-esportazzjoni',
  ' Overweeg dit te redigeren met [[dubbele blokhaken]].':
      ' Ikkunsidra li tirrediġih b\'[[parentesi kwadri doppji]].',
  ' Zonder context in de tekst is dit mogelijk geen persoonsgegeven.':
      ' Mingħajr kuntest fit-test, dan forsi lanqas huwa data personali.',
  'Leest je dia\'s na op identificatienummers, contactgegevens en andere privacygevoelige gegevens, en meldt ze bij de kwaliteitscontrole. Dit gebeurt volledig op dit apparaat; er wordt niets verstuurd. Het is een hulpmiddel, geen garantie: tekst in afbeeldingen en gegevens zonder herkenbaar patroon blijven buiten beeld.':
      'Jiċċekkja s-slides tiegħek għal numri ta\' identifikazzjoni, dettalji ta\' kuntatt u data oħra sensittiva għall-privatezza, u jirrappurtahom fil-kontroll tal-kwalità. Dan iseħħ kollu fuq dan l-apparat; xejn ma jintbagħat. Hija għajnuna, mhux garanzija: test fl-immaġni u data mingħajr xejra rikonoxxibbli jibqgħu moħbija.',
  'Mogelijk persoonsgegeven': 'Data personali possibbli',
  'Privacycontrole': 'Kontroll tal-privatezza',
  'Waarschuw bij mogelijke persoonsgegevens':
      'Wissi dwar data personali possibbli',
  'burgerservicenummer (BSN)': 'numru taċ-ċittadin (BSN)',
  'bankrekeningnummer (IBAN)': 'numru tal-kont bankarju (IBAN)',
  'e-mailadres': 'indirizz tal-email',
  'De TSA-handtekening is niet in-app geverifieerd; alleen de hash komt overeen.':
      'Il-firma tat-TSA mhijiex verifikata fl-app; jaqbel biss il-hash.',
  'Extern': 'Estern',
  'Van een externe URL opgehaald; het openen heeft die server benaderd.':
      'Miksub minn URL estern; il-ftuħ ikkuntattja dak is-server.',
  'AI-assistentie (staat standaard uit): kies je een zelf-gehoste of cloud-backend, dan worden de teksten of afbeeldingen die je laat verwerken naar dat adres gestuurd. Wat je hebt geredigeerd, gaat er eerst uit. Een lokaal AI-model op dit apparaat verstuurt niets.':
      'Assistenza AI (mitfija awtomatikament): jekk tagħżel backend self-hosted jew fis-sħaba, it-testi jew l-immaġni li tipproċessa jintbagħtu f\'dak l-indirizz. Dak li rrediġejt jitneħħa l-ewwel. Mudell AI lokali fuq dan l-apparat ma jibgħat xejn.',
  'Gegevens weglaten (redactie)': 'Tħalli barra data (redazzjoni)',
  'Zet je tekst tussen dubbele blokhaken, zoals [[het adres]], dan laat OciDeck die weg uit alles wat je toont en exporteert. Op de dia, in de presentatie, in de PDF, de PowerPoint en de HTML verschijnen alleen blokken.':
      'Poġġi t-test bejn parentesi kwadri doppji, bħal [[l-indirizz]], u OciDeck iħallih barra minn dak kollu li turi u tesporta. Fuq is-slide, fil-preżentazzjoni, fil-PDF, fil-PowerPoint u fl-HTML jidhru blokki biss.',
  'Weggelaten is écht weggelaten, niet afgedekt. De tekst zit niet als onzichtbare laag onder een zwart balkje in de PDF, niet in de sprekersnotities van de PowerPoint, en niet in de broncode van de HTML. Wie het bestand openmaakt, kan er niets uit terughalen.':
      'Imħolli barra jfisser tassew imħolli barra, mhux mgħotti. It-test ma jinsabx bħala saff inviżibbli taħt strixxa sewda fil-PDF, lanqas fin-noti tal-kelliem tal-PowerPoint, u lanqas fil-kodiċi sors tal-HTML. Min jiftaħ il-fajl ma jista\' jirkupra xejn minnu.',
  'Je eigen bestand verandert niet. De oorspronkelijke tekst blijft in je markdown staan; redactie geldt alleen voor wat je deelt. Zo houd je je eigen gegevens.':
      'Il-fajl tiegħek ma jinbidilx. It-test oriġinali jibqa\' fil-markdown tiegħek; ir-redazzjoni tapplika biss għal dak li taqsam. Hekk iżżomm id-data tiegħek.',
  'map/presentatie': 'folder/preżentazzjoni',
  'Gekoppelde test': 'Test marbut',
  'Maak eerst een checklist voor dit scope-object.':
      'L-ewwel oħloq lista ta\' kontroll għal dan l-oġġett tal-kamp.',
